def q423(stages, microbatches, stage_seconds=1):
    if min(stages, microbatches) < 1:
        raise ValueError("positive counts required")
    bubble = (stages - 1) / (microbatches + stages - 1)
    return (
        bubble,
        1 - bubble,
        2 * (microbatches + stages - 1) * stage_seconds,
    )
